And you’re right to be irritated: the “auto-comment / AST rewrite” features **are useful**, but they’re only safe when the source is already syntactically valid (or you run them on copies). In your case they **broke indentation** and test collection. So now we do the *fastest recovery* path: **restore from your known-good dump automatically**.

Below is **one script** that does everything.

---

## ✅ ONE SCRIPT: Archive old + rebuild clean under the SAME name

### 1) Go to the parent folder (where `ReflexAI-Integrations` exists)
```bat
cd C:\Users\v_sen\Documents\ChatGpt-Hackthon\Hack0001
```

### 2) Create and run this script
```bat
notepad REBUILD_REFLEXAI_FROM_DUMP.bat
```

Paste **exactly**:

```bat
@echo off
setlocal EnableExtensions EnableDelayedExpansion

REM === CONFIG ===
set "OLD_NAME=ReflexAI-Integrations"
set "NEW_NAME=ReflexAI-Integrations"
set "DUMP_REL=reflexai_code_dump\reflexai_code_122025_ 24750.txt"

REM === TIMESTAMP (safe for Windows folder names) ===
for /f "tokens=1-3 delims=/:. " %%a in ("%date% %time%") do (
  set "TS=%%a_%%b_%%c"
)
set "TS=%TS::=-%"
set "TS=%TS: =%"
set "ARCHIVE_NAME=%OLD_NAME%__ARCHIVE__%TS%"

echo ==================================================
echo ReflexAI REBUILD (from known-good dump)
echo Parent: %cd%
echo Archive old folder to: %ARCHIVE_NAME%
echo New clean folder name: %NEW_NAME%
echo Dump file (from old): %DUMP_REL%
echo ==================================================

if not exist "%OLD_NAME%\" (
  echo [ERROR] Folder not found: %OLD_NAME%
  exit /b 1
)

REM --- Verify dump exists in old folder ---
if not exist "%OLD_NAME%\%DUMP_REL%" (
  echo [ERROR] Dump file not found:
  echo         %OLD_NAME%\%DUMP_REL%
  echo [TIP] Check filename spacing inside reflexai_code_dump.
  exit /b 1
)

REM --- Archive old ---
ren "%OLD_NAME%" "%ARCHIVE_NAME%"
if errorlevel 1 (
  echo [ERROR] Failed to rename old folder.
  exit /b 1
)

REM --- Create new clean folder with same name ---
mkdir "%NEW_NAME%"
cd "%NEW_NAME%"

REM --- Copy dump into new root ---
copy "..\%ARCHIVE_NAME%\%DUMP_REL%" ".\dump.txt" >nul
if errorlevel 1 (
  echo [ERROR] Failed to copy dump into new folder.
  exit /b 1
)

REM --- Create restore_from_dump.py ---
> restore_from_dump.py (
  echo import os, re
  echo DUMP_FILE = "dump.txt"
  echo with open(DUMP_FILE, "r", encoding="utf-8") as f:
  echo^    content = f.read()
  echo blocks = re.split(r"-{10} FILE: (.+?) -{10}", content)
  echo for i in range(1, len(blocks), 2):
  echo^    rel_path = blocks[i].strip()
  echo^    code = blocks[i+1].lstrip("\n")
  echo^    d = os.path.dirname(rel_path)
  echo^    if d:
  echo^        os.makedirs(d, exist_ok=True)
  echo^    with open(rel_path, "w", encoding="utf-8") as wf:
  echo^        wf.write(code)
  echo^    print(f"[RESTORED] {rel_path}")
  echo print("\n✅ RESTORE COMPLETE")
)

REM --- Restore files from dump ---
python restore_from_dump.py
if errorlevel 1 (
  echo [ERROR] Restore failed.
  exit /b 1
)

REM --- Ensure src\reflexai logging_utils exists and is valid ---
mkdir src\reflexai >nul 2>nul

> src\reflexai\logging_utils.py (
  echo from datetime import datetime
  echo.
  echo def ts_print(*args, **kwargs):
  echo^    ts = datetime.now().strftime("%%H:%%M:%%S")
  echo^    print(f"[{ts}]", *args, **kwargs)
)

> src\reflexai\__init__.py (
  echo # ReflexAI package
)

REM --- Copy model + demo images (best-effort) ---
mkdir models >nul 2>nul
if exist "..\%ARCHIVE_NAME%\models\yolo11n.pt" copy "..\%ARCHIVE_NAME%\models\yolo11n.pt" "models\yolo11n.pt" >nul

mkdir assets\demo_images >nul 2>nul
if exist "..\%ARCHIVE_NAME%\assets\demo_images\*.jpg" copy "..\%ARCHIVE_NAME%\assets\demo_images\*.jpg" "assets\demo_images\" >nul

REM --- requirements.txt ---
> requirements.txt (
  echo opencv-python
  echo numpy
  echo ultralytics
)

echo.
echo ==================================================
echo NEXT: install deps + run webcam (no camera)
echo   cd "%cd%"
echo   pip install -r requirements.txt
echo   python runtime\run_webcam.py --no-camera
echo ==================================================
echo.
echo DONE.
pause
```

Save, then run:

```bat
REBUILD_REFLEXAI_FROM_DUMP.bat
```

